package flagdef_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/blackbirdworks/semaphore/internal/cache"
	"github.com/blackbirdworks/semaphore/modules/core/ffcontext"
	"github.com/blackbirdworks/semaphore/modules/core/flagdef"
)

// The golden file pins the result of every flag of the flag files of the repository for a set of contexts. It was
// generated by the engine before the segments existed (go test -run TestEquivalence with UPDATE_GOLDEN=1): a
// flag that does not use segments must keep evaluating byte for byte the same.
const (
	ctxEmpty = "empty"
	ctxBeta  = "beta"
)

const equivalenceGolden = "testdata/equivalence.golden.json"

type equivalenceCase struct {
	Metadata     map[string]any           `json:"metadata,omitempty"`
	RuleIndex    *int                     `json:"ruleIndex,omitempty"`
	RuleName     *string                  `json:"ruleName,omitempty"`
	Value        any                      `json:"value"`
	File         string                   `json:"file"`
	Flag         string                   `json:"flag"`
	Context      string                   `json:"context"`
	Variant      string                   `json:"variant"`
	Reason       flagdef.ResolutionReason `json:"reason"`
	ErrorCode    flagdef.ErrorCode        `json:"errorCode,omitempty"`
	ErrorMessage string                   `json:"errorMessage,omitempty"`
	Cacheable    bool                     `json:"cacheable"`
}

func equivalenceContexts() map[string]ffcontext.Context {
	return map[string]ffcontext.Context{
		ctxEmpty: ffcontext.NewEvaluationContext(""),
		"user1":  ffcontext.NewEvaluationContext("user1"),
		"random": ffcontext.NewEvaluationContext("random-key"),
		"admin": ffcontext.NewEvaluationContextBuilder("admin-1").
			AddCustom("admin", true).
			AddCustom("email", "a@b.c").
			Build(),
		ctxBeta: ffcontext.NewEvaluationContextBuilder("beta-9").
			AddCustom(ctxBeta, "true").
			AddCustom("name", "Ada").
			Build(),
		"teamAge": ffcontext.NewEvaluationContextBuilder("t-1").
			AddCustom("team", "team-123").
			AddCustom("age", 31).
			Build(),
		"segment":  ffcontext.NewEvaluationContextBuilder("s-1").AddCustom("segment", "beta-users").Build(),
		"longName": ffcontext.NewEvaluationContext(strings.Repeat("k", 300)),
	}
}

func equivalenceFiles(t *testing.T) []string {
	t.Helper()

	root := filepath.Join("..", "..", "..", "testdata")

	var files []string

	for _, pattern := range []string{"flag-config*.*", "multiple_files/*", "benchmark/*", "ffclient/*/*"} {
		matches, err := filepath.Glob(filepath.Join(root, pattern))
		require.NoError(t, err)

		for _, match := range matches {
			if strings.Contains(match, "flag-config-big") || strings.Contains(match, "invalid") {
				continue
			}

			info, statErr := os.Stat(match)
			require.NoError(t, statErr)

			if !info.IsDir() {
				files = append(files, match)
			}
		}
	}

	slices.Sort(files)

	return files
}

func collectEquivalence(t *testing.T) []equivalenceCase {
	t.Helper()

	contexts := equivalenceContexts()
	names := make([]string, 0, len(contexts))

	for name := range contexts {
		names = append(names, name)
	}

	slices.Sort(names)

	var cases []equivalenceCase

	for _, file := range equivalenceFiles(t) {
		content, err := os.ReadFile(file)
		require.NoError(t, err)

		format := strings.TrimPrefix(filepath.Ext(file), ".")

		flags, err := cache.ConvertToFlagStruct(content, format)
		if err != nil {
			continue
		}

		svc := flagdef.NewService()

		keys := make([]string, 0, len(flags))
		for key := range flags {
			keys = append(keys, key)
		}

		slices.Sort(keys)

		for _, key := range keys {
			dto := flags[key]
			flag := dto.Convert()

			if flag.IsValid(svc) != nil {
				continue
			}

			for _, ctxName := range names {
				value, details := flag.Value(key, contexts[ctxName], flagdef.Context{Service: svc})
				cases = append(cases, equivalenceCase{
					File: filepath.ToSlash(
						strings.TrimPrefix(file, filepath.Join("..", "..", "..")+string(filepath.Separator)),
					),
					Flag:         key,
					Context:      ctxName,
					Value:        value,
					Variant:      details.Variant,
					Reason:       details.Reason,
					ErrorCode:    details.ErrorCode,
					ErrorMessage: details.ErrorMessage,
					RuleIndex:    details.RuleIndex,
					RuleName:     details.RuleName,
					Cacheable:    details.Cacheable,
					Metadata:     details.Metadata,
				})
			}
		}
	}

	return cases
}

func TestEquivalenceOfFlagsWithoutSegments(t *testing.T) {
	t.Parallel()

	got, err := json.MarshalIndent(collectEquivalence(t), "", " ")
	require.NoError(t, err)

	if os.Getenv("UPDATE_GOLDEN") != "" {
		require.NoError(t, os.WriteFile(equivalenceGolden, append(got, '\n'), 0o600))

		return
	}

	want, err := os.ReadFile(equivalenceGolden)
	require.NoError(t, err)

	assert.JSONEq(t, string(want), string(got))
	assert.Greater(t, len(got), 10000, "the golden file covers the flag files of the repository")
}
